LABEL_02EC0A:
	DEC 2, XSP
	LD (XSP), A
	LD A, (0451A4h)
	CP A, (XSP)
	JRL NZ, LABEL_02ECBB
	CP (XSP), 002h
	JR ULE, LABEL_02EC38
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LD WA, (XBC + WA)
	AND WA, 0003h
	CP WA, 3
	JRL NZ, LABEL_02ECBB

LABEL_02EC38:
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LD WA, (XBC + WA)
	BIT 0, WA
	JR Z, LABEL_02EC65
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	ORW (XBC + WA), 0001h
	JR T, LABEL_02ECBB

